/*
 * shared/hooks/useOnboardingExitGuard.js. The web pushes a history entry and
 * catches "popstate"; the app catches the hardware back button the same way:
 * first step -> ask before leaving, later steps -> previous step.
 */
function useOnboardingExitGuard({ isFirstStep, onPreviousStep, onExit, hasUnsavedProgress = () => true }) {
  const [showExitModal, setShowExitModal] = useState(false)

  const handleStay = useCallback(() => {
    setShowExitModal(false)
  }, [])

  const handleExit = useCallback(() => {
    setShowExitModal(false)
    onExit?.()
  }, [onExit])

  const requestExit = useCallback(() => {
    if (hasUnsavedProgress()) {
      setShowExitModal(true)
      return
    }
    onExit?.()
  }, [hasUnsavedProgress, onExit])

  const handleBack = useCallback(() => {
    if (isFirstStep) {
      requestExit()
      return
    }
    onPreviousStep?.()
  }, [isFirstStep, onPreviousStep, requestExit])

  useEffect(() => {
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      if (isFirstStep) {
        requestExit()
        return true
      }
      onPreviousStep?.()
      return true
    })
    return () => sub.remove()
  }, [isFirstStep, onPreviousStep, requestExit])

  return { showExitModal, handleBack, handleStay, handleExit, requestExit }
}

const normalizePhoneDigits = (value) => {
  const digits = String(value || "").replace(/\D/g, "")
  return digits.slice(-10)
}

async function finalizeRestaurantPendingSubmission(navigate, phone, fcmOptions = {}) {
  const { fcmToken, platform } = fcmOptions
  const normalizedPhone = normalizePhoneDigits(phone || "")

  try {
    const userStr = localStore.getItem("restaurant_user")
    if (userStr) {
      const user = JSON.parse(userStr)
      user.status = "pending"
      localStore.setItem("restaurant_user", JSON.stringify(user))
    }
  } catch {}

  if (normalizedPhone) {
    localStore.setItem("restaurant_pendingPhone", normalizedPhone)
  }
  localStore.setItem("restaurant_pendingStatus", "pending")
  localStore.removeItem("restaurant_pendingMessage")

  try {
    syncPendingPartnerFcmQuick("restaurant", normalizedPhone, { fcmToken, platform })
  } catch {}

  if (localStore.getItem("restaurant_accessToken")) {
    try {
      persistModuleFcmToken("restaurant", { fcmToken, platform }).catch(() => {})
    } catch {}
  }

  /*
   * A "both" signup never reaches this function while still "both" — the
   * wizard's own step 3 branch (handleNext) intercepts it, runs steps 4-5
   * inline, and clears the intent itself once the hotel half is submitted
   * too. Getting here with the intent still set to "both" would only happen
   * if that flow was interrupted, so treat it the same as restaurant-only
   * rather than dropping the partner onto a stale hotel prompt.
   */
  clearOnboardingIntent()

  navigate("/food/restaurant/pending-verification", {
    replace: true,
    state: { phone: normalizedPhone },
  })
}

