const saveFileToDB = async (key, file) => {
  if (!file || !isUploadableFile(file)) return
  try {
    const { uri, name, type, size, width, height } = file
    localStore.setItem(ONBOARDING_FILE_KEY_PREFIX + key, JSON.stringify({ uri, name, type, size, width, height }))
  } catch (err) {
    debugError("Saving picked file failed:", err)
  }
}

const getFileFromDB = async (key) => {
  try {
    const raw = localStore.getItem(ONBOARDING_FILE_KEY_PREFIX + key)
    const file = raw ? JSON.parse(raw) : null
    return isUploadableFile(file) ? file : null
  } catch (err) {
    debugError("Loading picked file failed:", err)
    return null
  }
}

const deleteFileFromDB = async (key) => {
  try {
    localStore.removeItem(ONBOARDING_FILE_KEY_PREFIX + key)
  } catch (err) {
    debugError("Deleting picked file failed:", err)
  }
}

const getUploadableMenuFiles = (menuImages = []) =>
  (Array.isArray(menuImages) ? menuImages : [])
    .filter((img) => isUploadableFile(img))
    .slice(0, 10)

const persistMenuImagesToDB = async (menuImages = []) => {
  const uploadableMenuFiles = getUploadableMenuFiles(menuImages)
  for (let i = 0; i < 10; i++) {
    const file = uploadableMenuFiles[i]
    if (file) {
      await saveFileToDB(`menuImage_${i}`, file)
    } else {
      await deleteFileFromDB(`menuImage_${i}`)
    }
  }
}

const isUploadableFile = (value) =>
  Boolean(value) && typeof value === "object" && typeof value.uri === "string" && value.uri.length > 0 && !value.url

const normalizePincode = (value) => String(value || "").replace(/\D/g, "").slice(0, 6)

const getVerifiedPhoneFromStoredRestaurant = () => {
  try {
    const pending = localStore.getItem("restaurant_pendingPhone")
    if (pending && pending.trim()) {
      return pending.trim()
    }

    const storedUser = localStore.getItem("restaurant_user")
    if (!storedUser) return ""
    const user = JSON.parse(storedUser)
    const candidates = [
      user?.ownerPhone,
      user?.primaryContactNumber,
      user?.phone,
      user?.phoneNumber,
      user?.mobile,
      user?.contactNumber,
      user?.contact?.phone,
      user?.owner?.phone,
      user?.restaurant?.phone,
    ]
    const phone = candidates.find((value) => typeof value === "string" && value.trim())
    return phone ? phone.trim() : ""
  } catch {
    return ""
  }
}

const normalizeEmail = (val) => {
  let email = String(val || "").toLowerCase().trim()
  // Auto-correct common Gmail typos
  email = email.replace(/@(gnail|gamil|gimail|gnil)\.com$/i, "@gmail.com")
  return email
}

const normalizeAccountTypeValue = (value) => {
  const normalized = String(value || "").trim().toLowerCase()
  if (normalized === "saving" || normalized === "savings") return "Saving"
  if (normalized === "current") return "Current"
  return ""
}

const formatNameToCapital = (str) => {
  if (!str) return ""
  return str.split(" ").map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()).join(" ")
}

