  const handleExitAnyway = useCallback(() => {
    void (async () => {
      try {
        clearOnboardingFcmLocalState()
        clearOnboardingFromLocalStorage()
        clearOnboardingFileCache()
        await clearAllFilesFromDB()

        const hasSession = Boolean(localStore.getItem("restaurant_refreshToken"))
        if (hasSession) {
          await restaurantAPI.logout().catch(() => {})
        }
        clearModuleAuth("restaurant")
        clearAuthData()
        events.emit("restaurantAuthChanged")
      } catch (e) {
        debugError("Error clearing onboarding data on exit:", e)
      }
      navigate("/food/restaurant/login", { replace: true })
    })()
  }, [navigate])

